<script setup>import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import { Head, Link, router } from '@inertiajs/vue3'; const props=defineProps({asset:Object}); const remove=()=>{if(confirm(`Remove ${props.asset.name}?`)) router.delete(route('assets.destroy',props.asset.id));}; const details=[['Vendor',props.asset.vendor],['Model',props.asset.model],['Firmware',props.asset.firmware_version],['Internal IP',props.asset.internal_ip],['External IP',props.asset.external_ip],['Monitoring source',props.asset.data_source_type?.replace('_',' ')],['Criticality',props.asset.criticality]];</script>
<template><Head :title="asset.name"/><AuthenticatedLayout><template #header><div class="flex items-center justify-between"><div><p class="text-sm font-medium uppercase tracking-wide text-teal-700">{{ asset.asset_type }}</p><h1 class="text-2xl font-semibold text-slate-900">{{ asset.name }}</h1></div><div class="flex gap-2"><Link :href="route('assets.edit',asset.id)" class="rounded-lg border px-4 py-2 text-sm font-medium">Edit</Link><button @click="remove" class="rounded-lg border border-red-200 px-4 py-2 text-sm font-medium text-red-700">Remove</button></div></div></template><div class="mx-auto grid max-w-5xl gap-6 px-4 py-8 lg:grid-cols-[2fr_1fr]"><section class="rounded-xl border bg-white p-6 shadow-sm"><h2 class="text-lg font-semibold">Device details</h2><dl class="mt-5 grid gap-5 sm:grid-cols-2"><div v-for="([label,value]) in details" :key="label"><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">{{ label }}</dt><dd class="mt-1 capitalize text-slate-900">{{ value || 'Not recorded' }}</dd></div></dl><div class="mt-6 border-t pt-5"><h3 class="text-sm font-semibold">Notes and compensating controls</h3><p class="mt-2 whitespace-pre-wrap text-sm text-slate-600">{{ asset.notes || 'None recorded.' }}</p></div></section><aside class="space-y-4"><div class="rounded-xl border bg-white p-5 shadow-sm"><p class="text-xs font-semibold uppercase text-slate-500">Current exposure</p><p class="mt-2 text-lg font-semibold" :class="asset.is_internet_facing?'text-red-700':'text-emerald-700'">{{ asset.is_internet_facing ? 'Reachable from the internet' : 'Not known to be exposed' }}</p></div><div class="rounded-xl border bg-white p-5 shadow-sm"><p class="text-xs font-semibold uppercase text-slate-500">Location</p><p class="mt-2 font-semibold">{{ asset.site.name }}</p><p class="text-sm text-slate-500">{{ asset.process_area?.name || 'No process area assigned' }}</p></div></aside></div></AuthenticatedLayout></template>
